// TODO: mapeamento de campos AINDA NÃO CONFIRMADO -- escrito às cegas,
// sem ter visto uma resposta real do endpoint 'eaps'
// (hub_mse_endpoint.php?id=8&endpoint=2). Ajustar os nomes à ESQUERDA
// (fonte.<campo>) assim que tivermos uma amostra real; os nomes à
// DIREITA já são as colunas reais de `eap_tarefas`/`eap_cards_ativos`
// no MySQL (migration 008_eap.sql) -- não mudar sem mudar a migration
// junto.
//
// Node anterior está em Response Format = Text (n8n rejeitava como JSON
// direto) -- o texto cru chega aqui em $json.data. Parse manual: se
// falhar, joga o texto cru (até 1000 chars) no erro pra dar pra ler na
// execução do n8n e diagnosticar (aviso do PHP antes do JSON? XML? HTML
// de erro?).
const bruto = typeof $json === 'string' ? $json : ($json.data ?? $json.body ?? JSON.stringify($json));
let corpo;
try {
  corpo = JSON.parse(bruto);
} catch (e) {
  throw new Error('Resposta de eaps nao e JSON valido. Texto cru (ate 1000 chars): ' + String(bruto).slice(0, 1000));
}

const itens = Array.isArray(corpo?.data) ? corpo.data
            : Array.isArray(corpo) ? corpo
            : (() => { throw new Error('Envelope inesperado de eaps: ' + JSON.stringify(corpo).slice(0, 300)); })();

if (typeof corpo?.total === 'number' && corpo.total !== itens.length) {
  throw new Error(`eaps: API reportou total=${corpo.total} mas vieram ${itens.length} itens -- paginação não confirmada`);
}

const linhasEAP = itens.map(t => ({
  id: Number(t.id),
  id_obra: Number(t.id_obra),
  nome_obra: t.nome_obra,
  id_eap_grupo: t.id_eap != null ? Number(t.id_eap) : null,
  edt: t.edt,
  tarefa: t.tarefa,
  disciplina: t.disciplina,
  local: t.local,
  unidade: t.unidade,
  qtd: t.qtd,
  saldo_qtd: t.saldo_qtd,
  efetivo_previsto: t.efetivo_previsto,
  ponderacao_reais: t.ponderacao_reais,
  ponderacao_hht: t.ponderacao_hht,
  data_inicio: t.data_inicio,
  data_termino: t.data_termino,
  data_inicio_reprogramado: t.data_inicio_reprogramado,
  data_termino_reprogramado: t.data_termino_reprogramado,
  encarregado_nome: t.encarregado_nome,
}));

const linhasCards = itens.map(t => ({
  card_id: Number(t.id),
  id_eap_grupo: t.id_eap != null ? Number(t.id_eap) : null,
  nome_eap: t.nome_eap,
  id_obra: Number(t.id_obra),
  nome_obra: t.nome_obra,
  edt: t.edt,
  tarefa: t.tarefa,
  resp_planejamento: t.resp_planejamento,
  responsavel_encarregado: t.responsavel_encarregado,
  supervisor_coordenador: t.supervisor_coordenador,
  sincronizado_em: new Date().toISOString(),
}));

return [{ json: { linhasEAP, linhasCards } }];

// Monta o INSERT ... ON DUPLICATE KEY UPDATE como STRING pronta -- mesmo
// motivo do snippet de Restrições/OC: o campo "Query Parameters" do node
// MySQL nativo (n8n 2.4) não é confiável entre versões, então a query
// inteira vira uma expressão fx (esta) em vez de parâmetros do node.
const escapar = (v) => "'" + String(v).replace(/\\/g, '\\\\').replace(/'/g, "\\'") + "'";
const valorSql = (v) => {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'number') return Number.isFinite(v) ? String(v) : 'NULL';
  return escapar(v);
};

const COLUNAS = [
  'id', 'id_obra', 'nome_obra', 'id_eap_grupo', 'edt', 'tarefa', 'disciplina',
  'local', 'unidade', 'qtd', 'saldo_qtd', 'efetivo_previsto', 'ponderacao_reais',
  'ponderacao_hht', 'data_inicio', 'data_termino', 'data_inicio_reprogramado',
  'data_termino_reprogramado', 'encarregado_nome',
];

const linhas = $json.linhasEAP;
if (!linhas.length) return [{ json: { sql: 'SELECT 1' } }]; // nada pra gravar nesta rodada

const tuplas = linhas.map(l => '(' + COLUNAS.map(c => valorSql(l[c])).join(',') + ')').join(',\n');
const atualiza = COLUNAS.filter(c => c !== 'id').map(c => `\`${c}\` = VALUES(\`${c}\`)`).join(', ');
const colunasSql = COLUNAS.map(c => `\`${c}\``).join(',');
const sql = `INSERT INTO eap_tarefas (${colunasSql}) VALUES ${tuplas} ON DUPLICATE KEY UPDATE ${atualiza}`;

return [{ json: { sql } }];

